/**
 * The browser's dictionaries, one chunk per language.
 *
 * `LocaleProvider` used to import th, en-GB and en-US statically, which put
 * about 1 MB of JSON (320 KB gzip) in the bundle every visitor downloads. Now:
 *
 *   - `en-GB` is the base. It stays in the shared bundle: it is the fallback
 *     for every key a language lacks, and the English the first paint can
 *     always render without waiting for anything.
 *   - `en-US` is the base plus `lib/i18n/overlays/en-US.json` (the 58 keys
 *     that differ, generated by `scripts/i18n-build-en-us-overlay.js`), so the
 *     US variant costs 3 KB gzip instead of a second copy of the English.
 *   - The other 17 languages are separate `import()` chunks, fetched when a
 *     visitor's language needs them and never for anyone else.
 *
 * This module has no React and no `'use client'`; it is safe to import from
 * either side. Server-only callers that need every dictionary at once
 * (`generateMetadata`, Server Components) use `lib/i18n/get-dictionary.ts`.
 *
 * @module lib/i18n/client-dictionaries
 */

import enGBDict from '@/lib/i18n/dictionaries/en-GB.json';
import enUSOverlay from '@/lib/i18n/overlays/en-US.json';

export type Dictionary = Record<string, string>;

const BASE_LANGUAGE = 'en-GB';
const OVERLAY_LANGUAGE = 'en-US';

/** The fallback dictionary: English (UK). Always available synchronously. */
export const BASE_DICTIONARY: Dictionary = enGBDict;

type Loader = () => Promise<{ default: Dictionary }>;

/**
 * One literal `import()` per language, so the bundler cuts one chunk for each
 * and a language added to `SUPPORTED_LANGUAGES` without an entry here is
 * caught by `__tests__/lib/i18n/client-dictionaries.test.ts`.
 */
const LOADERS: Record<string, Loader> = {
  ar: () => import('@/lib/i18n/dictionaries/ar.json'),
  de: () => import('@/lib/i18n/dictionaries/de.json'),
  es: () => import('@/lib/i18n/dictionaries/es.json'),
  fr: () => import('@/lib/i18n/dictionaries/fr.json'),
  hi: () => import('@/lib/i18n/dictionaries/hi.json'),
  id: () => import('@/lib/i18n/dictionaries/id.json'),
  it: () => import('@/lib/i18n/dictionaries/it.json'),
  ja: () => import('@/lib/i18n/dictionaries/ja.json'),
  ko: () => import('@/lib/i18n/dictionaries/ko.json'),
  pt: () => import('@/lib/i18n/dictionaries/pt.json'),
  'pt-BR': () => import('@/lib/i18n/dictionaries/pt-BR.json'),
  th: () => import('@/lib/i18n/dictionaries/th.json'),
  tr: () => import('@/lib/i18n/dictionaries/tr.json'),
  ur: () => import('@/lib/i18n/dictionaries/ur.json'),
  vi: () => import('@/lib/i18n/dictionaries/vi.json'),
  zh: () => import('@/lib/i18n/dictionaries/zh.json'),
  'zh-TW': () => import('@/lib/i18n/dictionaries/zh-TW.json'),
};

/** The languages that load as their own chunk. */
export const CHUNKED_LANGUAGES: readonly string[] = Object.keys(LOADERS);

/** Dictionaries that have finished loading, by language. */
const loaded = new Map<string, Dictionary>();
/** In-flight or finished loads, by language: one promise per language. */
const pending = new Map<string, Promise<Dictionary>>();

let enUSDictionary: Dictionary | undefined;

/**
 * The dictionary for `language` if it is available without waiting (the
 * base, the US overlay, or a chunk that has already loaded); otherwise
 * undefined. An unknown language is the base, as it always was.
 */
export function peekDictionary(language: string): Dictionary | undefined {
  if (language === BASE_LANGUAGE) return BASE_DICTIONARY;
  if (language === OVERLAY_LANGUAGE) {
    enUSDictionary ??= { ...BASE_DICTIONARY, ...enUSOverlay };
    return enUSDictionary;
  }
  if (!(language in LOADERS)) return BASE_DICTIONARY;
  return loaded.get(language);
}

/**
 * Loads the dictionary for `language`. The returned promise is the same one
 * for every caller, so it can be handed to React's `use()`; it never rejects:
 * a chunk that cannot be fetched resolves to the base (English) and is
 * forgotten, so the next call tries again.
 */
export function loadDictionary(language: string): Promise<Dictionary> {
  const ready = peekDictionary(language);
  if (ready) return Promise.resolve(ready);

  const inFlight = pending.get(language);
  if (inFlight) return inFlight;

  const load = LOADERS[language];
  if (!load) return Promise.resolve(BASE_DICTIONARY);

  const promise = (async (): Promise<Dictionary> => {
    try {
      const mod = await load();
      const dictionary = mod.default || {};
      loaded.set(language, dictionary);
      return dictionary;
    } catch {
      pending.delete(language);
      return BASE_DICTIONARY;
    }
  })();
  pending.set(language, promise);
  return promise;
}

/** Loads several languages ahead of time (tests, and a future prefetch). */
export async function preloadDictionaries(
  languages: readonly string[]
): Promise<void> {
  await Promise.all(languages.map((language) => loadDictionary(language)));
}
